"""Copy every settlement from the Clearwell Settlements API into settlements.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.request

QUERY = """query Settlements($after: String) {
  settlements(first: 100, after: $after) {
    nodes { id batchDate amountCents currency status }
    pageInfo { endCursor hasNextPage }
  }
}"""


def graphql(url, query, variables=None):
    body = json.dumps({"query": query, "variables": variables or {}}).encode()
    req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})
    retries = 0
    while True:
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                result = json.load(resp)
            break
        except urllib.error.HTTPError as exc:
            # 429 Too Many Requests: wait Retry-After seconds, then retry
            # the identical request (same query, operation, variables).
            if exc.code == 429 and retries < 10:
                delay = exc.headers.get("Retry-After", "1")
                try:
                    delay = max(0, int(delay))
                except (TypeError, ValueError):
                    delay = 1
                time.sleep(delay)
                retries += 1
                continue
            raise
    if result.get("errors"):
        raise RuntimeError(result["errors"])
    return result["data"]


def fetch_settlements(url):
    """Traverse every v2 page, keeping the last version of each settlement id."""
    # A malformed or expired cursor aborts the traversal; start again from the
    # beginning without `after` (a bounded number of times).
    for attempt in range(3):
        settlements = {}
        after = None
        restarted = False
        while True:
            try:
                data = graphql(url, QUERY, {"after": after})["settlements"]
            except RuntimeError:
                if after is not None and attempt < 2:
                    restarted = True
                    break
                raise
            for node in data["nodes"]:
                # Amended settlements are re-delivered later in the traversal;
                # id is the key and the last version wins.
                settlements[node["id"]] = node
            page_info = data["pageInfo"]
            if not page_info["hasNextPage"]:
                return list(settlements.values())
            # Short or empty pages can still have hasNextPage true.
            after = page_info["endCursor"]
        if not restarted:
            break
    raise RuntimeError("could not complete settlement traversal")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="settlements.jsonl")
    args = ap.parse_args()
    settlements = fetch_settlements(f"{args.base_url.rstrip('/')}/v2/graphql")
    with open(args.out, "w") as f:
        for s in settlements:
            f.write(json.dumps(s) + "\n")
    print(f"reconciled {len(settlements)} settlements")


if __name__ == "__main__":
    main()

